"""Original MIT slot-2 FM-PAC setup for the original Philips/SCC-I fixture.
Executes from system page 0 while accessing the expansion latch and FM-PAC.
No vendor ROM, reference implementation code or commercial assets.
"""
from pathlib import Path
root = Path(__file__).parent
rom = bytearray(32768)
for line in (root / 'philips-system.hex').read_text().splitlines():
    if line.startswith('#'):
        continue
    offset, data = line.split(':')
    start = int(offset, 16)
    data = bytes.fromhex(data)
    rom[start:start + len(data)] = data
rom[:3] = bytes([0xc3, 0, 5])
# DI; slot 2 pages 1/3; select subslot 1 page 1; enable FM I/O;
# restore disk subslot 0 and default primary slots; enter original system init.
code = bytes.fromhex('f3 3e 98 d3 a8 3e 04 32 ff ff 3e 01 32 f6 7f 3e 00 32 ff ff 3e f0 d3 a8 c3 00 01')
rom[0x500:0x500+len(code)] = code
lines = ['# Original MIT Z80 diagnostic. Generated by fm-pac-disk.py from philips-system.hex.']
for start in range(0, len(rom), 16):
    data = rom[start:start+16]
    if any(data):
        lines.append(f'{start:04x}: ' + data.hex(' '))
(root / 'fm-pac-system.hex').write_text('\n'.join(lines)+'\n')
